// rl_cut1 helper a2: drawing kit for the S21d-l finished stills (4H 4I 5A-5F 6C). The stills are 2880 px wide; the stage is
// 2560, so every still pixel maps to the stage at K. IMG/LAY come from _cut1b_data.ts (generated by workers/rl_cut1/swap/a2/prep_assets.py).
import React from 'react';
import { AbsoluteFill, Img, staticFile } from 'remotion';
import { clamp } from '../../ease';
import { Quad } from '../../blocks/ScreenInsert';
import { W, H } from '../s03/_lib';
import { IMG, LAY } from './_cut1b_data';

export { IMG, LAY };
export const K = W / 2880;
export type ImgKey = keyof typeof IMG;
export const st = (p: number[]): [number, number] => [p[0] * K, p[1] * K];
export const quadSt = (q: number[][]): Quad => q.map((p) => st(p)) as Quad;

/** a still (or a cropped RGBA layer) at its own place on the stage, optionally offset (dx, dy in still px) */
export const Lyr: React.FC<{ n: ImgKey; dx?: number; dy?: number; style?: React.CSSProperties; opacity?: number; filter?: string }> = ({ n, dx = 0, dy = 0, style, opacity = 1, filter }) => {
  const a = IMG[n];
  return <Img src={staticFile(a.src)} style={{ position: 'absolute', left: (a.x + dx) * K, top: (a.y + dy) * K, width: a.w * K, height: a.h * K, opacity, filter, ...style }} />;
};

/** stage camera for plates taller than the stage (T11: 2560 x 2400 on the stage): like s03 Cam, clamped to the plate (pw x ph) */
export const CamT: React.FC<{ cx: number; cy: number; s: number; ph: number; children: React.ReactNode }> = ({ cx, cy, s, ph, children }) => {
  const hw = W / 2 / s, hh = H / 2 / s;
  const x = clamp(cx, hw, W - hw), y = clamp(cy, hh, ph - hh);
  return (
    <AbsoluteFill style={{ transformOrigin: '0 0', transform: `translate(${W / 2}px, ${H / 2}px) scale(${s.toFixed(5)}) translate(${(-x).toFixed(2)}px, ${(-y).toFixed(2)}px)` }}>
      {children}
    </AbsoluteFill>
  );
};
